/* Global Styles & Reset */
:root {
  --primary-color: #0070f3;
  --primary-hover: #0051a8;
  --bg-color: #fafafa;
  --card-bg: #ffffff;
  --text-color: #333333;
  --text-muted: #666666;
  --border-color: #eaeaea;
  --error-bg: #fee2e2;
  --error-text: #991b1b;
  --error-border: #fca5a5;
  --radius: 8px;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --transition: all 0.2s ease-in-out;
}

body {
  margin: 0;
  padding: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-color);
}

/* Gallery Container */
.gallery-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 40px 20px;
}

.header {
  text-align: center;
  margin-bottom: 40px;
}

.header h1 {
  font-size: 2.5rem;
  margin: 0 0 10px 0;
  color: #111;
}

.header p {
  font-size: 1.1rem;
  color: var(--text-muted);
  margin: 0;
}

/* Error Banner */
.error-banner {
  background-color: var(--error-bg);
  border: 1px solid var(--error-border);
  color: var(--error-text);
  padding: 12px 20px;
  border-radius: var(--radius);
  margin-bottom: 30px;
  font-weight: 500;
}

.error-banner p {
  margin: 0;
}

/* Upload Section */
.upload-section {
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 30px;
  margin-bottom: 40px;
  box-shadow: var(--shadow);
}

.upload-section h2 {
  margin-top: 0;
  margin-bottom: 20px;
  font-size: 1.5rem;
}

.upload-form {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

@media (min-width: 640px) {
  .upload-form {
    flex-direction: row;
    align-items: center;
  }
}

.file-input-wrapper {
  flex: 1;
}

.file-input {
  width: 100%;
  padding: 10px;
  border: 2px dashed var(--border-color);
  border-radius: var(--radius);
  background-color: #f9f9f9;
  cursor: pointer;
  box-sizing: border-box;
  transition: var(--transition);
}

.file-input:hover {
  border-color: var(--primary-color);
}

.submit-btn {
  background-color: var(--primary-color);
  color: #ffffff;
  border: none;
  padding: 12px 24px;
  border-radius: var(--radius);
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: var(--transition);
  white-space: nowrap;
}

.submit-btn:hover {
  background-color: var(--primary-hover);
}

/* Gallery Section */
.gallery-section h2 {
  font-size: 1.8rem;
  margin-bottom: 24px;
  border-bottom: 2px solid var(--border-color);
  padding-bottom: 10px;
}

.empty-message {
  text-align: center;
  color: var(--text-muted);
  font-size: 1.1rem;
  padding: 40px 0;
}

/* Grid layout */
.image-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 30px;
}

.image-card {
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow);
  transition: var(--transition);
  display: flex;
  flex-direction: column;
}

.image-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
}

.image-wrapper {
  position: relative;
  width: 100%;
  padding-top: 75%; /* 4:3 Aspect Ratio */
  background-color: #f0f0f0;
}

.gallery-image {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: contain;
  transition: var(--transition);
}

.image-info {
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1;
}

.filename {
  margin: 0;
  font-weight: 600;
  font-size: 1rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.dimensions {
  margin: 0;
  color: var(--text-muted);
  font-size: 0.875rem;
}

.view-link {
  margin-top: auto;
  align-self: flex-start;
  color: var(--primary-color);
  text-decoration: none;
  font-weight: 500;
  font-size: 0.875rem;
  transition: var(--transition);
}

.view-link:hover {
  color: var(--primary-hover);
  text-decoration: underline;
}

